/// Key location: iced -> Servo.
pub fn map_location(location: IcedLocation) -> FrostLocation {
    match location {
        IcedLocation::Standard => FrostLocation::Standard,
        IcedLocation::Left => FrostLocation::Left,
        IcedLocation::Right => FrostLocation::Right,
        IcedLocation::Numpad => FrostLocation::Numpad,
    }
}

/// Modifier state: iced bitflags -> Servo (`keyboard-types`) bitflags.
pub fn map_modifiers(mods: IcedModifiers) -> FrostModifiers {
    let mut out = FrostModifiers::empty();
    if mods.shift() {
        out |= FrostModifiers::SHIFT;
    }
    if mods.control() {
        out |= FrostModifiers::CONTROL;
    }
    if mods.alt() {
        out |= FrostModifiers::ALT;
    }
    if mods.logo() {
        out |= FrostModifiers::META;
    }
    if mods.contains(IcedModifiers::CAPS_LOCK) {
        out |= FrostModifiers::CAPS_LOCK;
    }
    out
}

/// Logical key: iced -> Servo. Printable characters keep their text;
/// named keys go through [`map_named`].
pub fn map_key(key: &IcedKey) -> FrostKey {
    match key {
        IcedKey::Character(c) => FrostKey::Character(c.to_string()),
        IcedKey::Named(named) => FrostKey::Named(map_named(*named)),
        IcedKey::Unidentified => FrostKey::Named(FrostNamedKey::Unidentified),
    }
}

/// Logical key with the key event's produced text: iced -> Servo.
///
/// winit's logical key is the UNSHIFTED character for shifted
/// punctuation on X11: Shift+; arrives as `Key::Character(";")`, while
/// the event's `text` is the character actually produced (`":"`). The
/// native iced text input uses `text` (so the address bar types `:`),
/// but the webview was fed only the logical key — page text inputs got
/// `;` instead of `:`, so no `http(s)` URL could ever be typed into a
/// page (found 2026-11-13: the settings homepage kept submitting
/// `https;//example.com` and the server rightly rejected it).
///
/// Prefer `text` for printable (`Character`) keys only. Named keys keep
/// their logical key: `text` for Enter is `"\r"`, which Servo must not
/// see as typed text (form submission and shortcuts need the named key).
///
/// Round 4: never prefer `text` while Control or Meta (Super/Logo) is
/// held — those are shortcut chords, not text. Winit reports the
/// produced text for Ctrl+A as `"\x01"` (the control character), and
/// preferring it sent `Character("\x01")` to Servo, whose shortcut
/// matcher compares against `'A'` and never matches — so Ctrl+A
/// select-all silently did nothing (gate 2026-11-14: the page saw
/// keydown `U+1+ctrl`, keyup `a+ctrl`, selection stayed `5..5`). With
/// a shortcut modifier held the logical key IS the shortcut key, so
/// `map_key` (the logical key) is used instead. Alt alone is left
/// alone: AltGr text entry on non-US layouts goes through Alt, and
/// Ctrl+Alt chords already include Control.
pub fn map_key_with_text(
    key: &IcedKey,
    text: Option<&str>,
    modifiers: IcedModifiers,
) -> FrostKey {
    if modifiers.control() || modifiers.logo() {
        return map_key(key);
    }
    match (key, text) {
        (IcedKey::Character(_), Some(t)) if !t.is_empty() => {
            FrostKey::Character(t.to_string())
        },
        _ => map_key(key),
    }
}

/// Mouse button: iced -> Servo.
pub fn map_button(button: IcedButton) -> FrostMouseButton {
    match button {
        IcedButton::Left => FrostMouseButton::Primary,
        IcedButton::Right => FrostMouseButton::Secondary,
        IcedButton::Middle => FrostMouseButton::Auxiliary,
        IcedButton::Back => FrostMouseButton::Back,
        IcedButton::Forward => FrostMouseButton::Forward,
        // Extra buttons (X1/X2/…) have no Servo counterpart; Auxiliary is
        // the least surprising mapping.
        IcedButton::Other(_) => FrostMouseButton::Auxiliary,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use cosmic::iced::keyboard::key::Named as IcedNamedKey;

    #[test]
    fn shifted_punctuation_prefers_text() {
        // Shift+; on X11: logical key ";" but produced text ":".
        let key = IcedKey::Character(";".into());
        assert_eq!(
            map_key_with_text(&key, Some(":"), IcedModifiers::SHIFT),
            FrostKey::Character(":".to_string())
        );
    }

    #[test]
    fn unshifted_character_keeps_text() {
        let key = IcedKey::Character("a".into());
        assert_eq!(
            map_key_with_text(&key, Some("a"), IcedModifiers::empty()),
            FrostKey::Character("a".to_string())
        );
    }

    #[test]
    fn named_keys_ignore_text() {
        // Enter's text is "\r" — it must stay the named key.
        let key = IcedKey::Named(IcedNamedKey::Enter);
        assert_eq!(
            map_key_with_text(&key, Some("\r"), IcedModifiers::empty()),
            FrostKey::Named(FrostNamedKey::Enter)
        );
    }

    #[test]
    fn no_text_falls_back_to_logical_key() {
        let key = IcedKey::Character(";".into());
        assert_eq!(
            map_key_with_text(&key, None, IcedModifiers::empty()),
            FrostKey::Character(";".to_string())
        );
    }

    #[test]
    fn control_chord_ignores_control_character_text() {
        // Ctrl+A on X11: logical key "a" but produced text "\x01".
        // Servo's shortcut matcher compares against 'A'; sending
        // "\x01" meant select-all never fired (Round 4 gate).
        let key = IcedKey::Character("a".into());
        assert_eq!(
            map_key_with_text(&key, Some("\x01"), IcedModifiers::CTRL),
            FrostKey::Character("a".to_string())
        );
    }

    #[test]
    fn meta_chord_ignores_text() {
        let key = IcedKey::Character("a".into());
        assert_eq!(
            map_key_with_text(&key, Some("\x01"), IcedModifiers::LOGO),
            FrostKey::Character("a".to_string())
        );
    }

    #[test]
    fn control_shift_chord_ignores_text() {
        // Ctrl+Shift+; is a shortcut chord, not a ":" keystroke.
        let key = IcedKey::Character(";".into());
        assert_eq!(
            map_key_with_text(
                &key,
                Some(":"),
                IcedModifiers::CTRL | IcedModifiers::SHIFT
            ),
            FrostKey::Character(";".to_string())
        );
    }
}
